import { Fragment } from './fragment.mjs';

export class Furl {
  constructor(rawUrl) {
    const url = String(rawUrl);
    const separatorIndex = url.indexOf('#');

    this._base = separatorIndex === -1 ? url : url.slice(0, separatorIndex);
    this.fragment =
      separatorIndex === -1 ? new Fragment('') : new Fragment(url.slice(separatorIndex + 1));
  }

  get url() {
    const fragment = String(this.fragment);

    if (fragment === '') {
      return this._base;
    }

    return `${this._base}#${fragment}`;
  }
}

export function furl(rawUrl) {
  return new Furl(rawUrl);
}

